#include <iostream>
using namespace std;

int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int number;
    cin >> number;

    int r = 2 * (number - 1);
    int c = number - 1;

    cout << factorial(r) / (factorial(c) * factorial(c));
    return 0;
}

